use std::{env,fs,io::{self,Write},process};use caveat_runtime::{ast::{Program,Statement},eval,parser,NodeKind};
fn main(){let mut args=env::args().skip(1);let mut interactive=false;let mut path=None;for a in args.by_ref(){if a=="--interactive"||a=="-i"{interactive=true}else{path=Some(a)}}let path=path.unwrap_or_else(||{eprintln!("usage: caveat [--interactive] <file.cav>");process::exit(2)});let source=fs::read_to_string(&path).unwrap_or_else(|e|{eprintln!("caveat: {e}");process::exit(1)});let mut p=parser::parse(&source).unwrap_or_else(|e|{eprintln!("parse error: {e}");process::exit(1)});
if interactive{let select_indices:Vec<usize>=p.statements.iter().enumerate().filter_map(|(i,s)|matches!(s,Statement::Select{..}).then_some(i)).collect();for i in select_indices{let(choice,current)=match &p.statements[i]{Statement::Select{choice,option}=>(choice.clone(),option.clone()),_=>continue};let preview=eval::evaluate(&Program::new(p.statements[..i].to_vec())).unwrap_or_else(|e|{eprintln!("evaluation error before choice: {e}");process::exit(1)});let cp=preview.choices.get(&choice).unwrap_or_else(||{eprintln!("unknown choice: {choice}");process::exit(1)});println!("\nCAVEAT choice: {choice}");println!("Options: {}",cp.options.join(" / "));if !cp.retaining.is_empty(){println!("Unresolved items retained by this decision: {}",cp.retaining.len())}let picked=loop{print!("> ");io::stdout().flush().unwrap();let mut input=String::new();io::stdin().read_line(&mut input).unwrap();let pick=input.trim().to_lowercase();if cp.options.contains(&pick){break pick}if input.is_empty(){break current.clone()}println!("Choose one of: {}",cp.options.join(", "));};if let Statement::Select{option,..}=&mut p.statements[i]{*option=picked;}}}
let r=eval::evaluate(&p).unwrap_or_else(|e|{eprintln!("evaluation error: {e}");process::exit(1)});println!("\nCAVEAT: {} statements -> {} graph nodes, {} edges, {} history events",p.statements.len(),r.graph.nodes.len(),r.graph.edges.len(),r.history.len());if let Some(b)=&r.resources{println!("resources: initial={} spent={} remaining={} exhausted={}",b.initial,b.spent,b.remaining,b.exhausted)}for(name,id)in&r.symbols{if let Some(NodeKind::Commitment{open,stop_reason,..})=r.graph.nodes.get(id){println!("commit {name}: open={open} stop={stop_reason:?}")}}}
